	// WORLD-003: the main-log, sub-log and gate sockets are gone. The Login link (login_link.cpp, started by the
	// host) replaces them, and the game data the log server pushed is read from GameData\ instead.
	bLoadGameDataFiles();

	m_bF1pressed = m_bF4pressed = m_bF12pressed = FALSE;
	
	// Server shutdown process variable. When set, no new connections are accepted and 50 players per timer tick are disconnected.
	m_bOnExitProcess = FALSE;
	
	// Precompute the SkillSSN points.
	for (i = 0; i <= 100; i++) {
		m_iSkillSSNpoint[i] = _iCalcSkillSSNpoint(i);
	}

	// Set day / night mode
	GetLocalTime(&SysTime);
