		break;				   

	case DEF_OWNERTYPE_NPC:
		// Attacking a dead NPC means nothing.
		if (m_pNpcList[sTargetH]->m_cBehavior == DEF_BEHAVIOR_DEAD) return;
		// Action Limit 1 means being attacked has no effect. (shopkeepers etc.)
		if (m_pNpcList[sTargetH]->m_cActionLimit == 1) return;
		// Decrease the NPC's HP.
