int CGame::iGetNpcRelationship(int iWhatH, int iRecvH)
{
	if (m_pClientList[iRecvH] == NULL) return 0;
	if (m_pNpcList[iWhatH] == NULL) return 0;

	int rtn = 0x0000;

	switch (m_pNpcList[iWhatH]->m_cSide) {
	case 0:	// Neutral
		break;

	case 10: // An NPC that attacks everyone
		rtn |= 0x0001 << 3;
		break;

	case 1:	// Belongs to aresden (guards, shopkeepers)
		rtn |= 0x0001 << 2;
		rtn |= 0x0001 << 1;
		break;

	case 2:	// Belongs to elvine (guards, shopkeepers)
		rtn |= 0x0001 << 2;
		break;
	}

	return rtn;
}


