					// v2.03 912 Max attribute value is 7 when the item level is 2 or less
					if ((iGenLevel <= 2) && (dwValue > 7)) dwValue = 7;
				
					// Set the item Main attribute and value
					pItem->m_dwAttribute = NULL;
					dwType  = dwType << 20;
					dwValue = dwValue << 16;
					pItem->m_dwAttribute = pItem->m_dwAttribute | dwType | dwValue;

