			iSoX = iSoM = 0;
			for (i = 0; i < DEF_MAXITEMS; i++)
			if (m_pClientList[iClientH]->m_pItemList[i] != NULL) {
				switch (m_pClientList[iClientH]->m_pItemList[i]->m_sIDnum) {
				case 656: iSoX++; iSoxH = i; break; // Stone of Xelima
				case 657: iSoM++; iSomH = i; break; // Stone of Merien
				}
			}
			
			// There is a Stone of Merien.
