/////////////////////////////////////////////////////////////////////////////////
//	int bProbabilityTable(int x,int y,int iTable) 
//	Arguments :: x skill level (20-100), y crop level (20-100),
//			iTable 1 :: hit success chance
//				   2 :: crop drop chance
//			return 0 :: false, zero chance.
//				   Rolled within 1-100; return the applied chance..
/////////////////////////////////////////////////////////////////////////////////
int CGame::bProbabilityTable(int x,int y,int iTable) 
{
	int iProb;
	int iX,iY;

	iX = (x - 20) / 10;
	iY = (y - 20) / 10;
	
	if( iX < 0 || iX > 8) return 0;
	if( iY < 0 || iY > 8) return 0;

	iProb = iDice(1,100);

	if(iTable == 1){
		if( SKILLCROPSTABLE[iX][iY] >= iProb )
			return SKILLCROPSTABLE[iX][iY];
		else
			return 0;
	}
	else if(iTable == 2){
		if( CROPSDROPTABLE[iX][iY] >= iProb )
			return CROPSDROPTABLE[iX][iY];
		else
			return 0;
	}
	else return 0;
}



















